"/**
 * Calcula la edad exacta en años dado una fecha de nacimiento.
 */
function calcularEdadEnAnos(fechaNacimiento) {
    const hoy = new Date();
    const nacimiento = new Date(fechaNacimiento);
    let edad = hoy.getFullYear() - nacimiento.getFullYear();
    const m = hoy.getMonth() - nacimiento.getMonth();

    if (m < 0 || (m === 0 && hoy.getDate() < nacimiento.getDate())) {
        edad--;
    }
    return edad;
}

module.exports = { calcularEdadEnAnos };"

"const prisma = require('../prismaClient');
const { calcularEdadEnAnos } = require('../utils/ageCalculator');

class ResultadoService {
    /**
     * Valida si un resultado numérico está fuera de los rangos de referencia dinámicos.
     */
    async validarResultado(resultadoValor, parametroId, pacienteId) {
        if (resultadoValor === null || isNaN(resultadoValor)) {
            return false;
        }

        const paciente = await prisma.paciente.findUnique({
            where: { id: pacienteId }
        });

        if (!paciente) throw new Error('Paciente no encontrado');

        const edad = calcularEdadEnAnos(paciente.fecha_nacimiento);
        const sexo = paciente.sexo; // 'M' o 'F'

        // Buscar el rango de referencia que aplica para esta edad y sexo
        const rangos = await prisma.rangoReferenciaHumano.findMany({
            where: {
                parametro_id: parametroId,
                OR: [
                    { sexo: sexo },
                    { sexo: 'Ambos' }
                ],
                edad_min_anos: { lte: edad },
                edad_max_anos: { gte: edad }
            }
        });

        // Si no hay rango definido para esa edad/sexo, no podemos marcarlo como fuera de rango
        if (rangos.length === 0) return false;

        const rango = rangos[0]; 
        const valorNum = parseFloat(resultadoValor);

        if (rango.min_valor !== null && valorNum < parseFloat(rango.min_valor)) return true;
        if (rango.max_valor !== null && valorNum > parseFloat(rango.max_valor)) return true;

        return false;
    }
}

module.exports = new ResultadoService();"

"const prisma = require('../prismaClient');

exports.getAllPacientes = async (req, res) => {
    try {
        const pacientes = await prisma.paciente.findMany({
            orderBy: { fecha_registro: 'desc' }
        });
        res.json(pacientes);
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
};

exports.getPacienteById = async (req, res) => {
    try {
        const paciente = await prisma.paciente.findUnique({
            where: { id: parseInt(req.params.id) },
            include: { ordenes: true }
        });
        if (!paciente) return res.status(404).json({ error: 'Paciente no encontrado' });
        res.json(paciente);
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
};

exports.createPaciente = async (req, res) => {
    try {
        const data = req.body;
        // Parsear fecha
        if (data.fecha_nacimiento) {
            data.fecha_nacimiento = new Date(data.fecha_nacimiento);
        }
        const paciente = await prisma.paciente.create({
            data
        });
        res.status(201).json(paciente);
    } catch (error) {
        res.status(400).json({ error: error.message });
    }
};"

