exports.getOrdenById = async (req, res) => {
    try {
        const orden = await prisma.ordenExamen.findUnique({
            where: { id: parseInt(req.params.id) },
            include: { paciente: true, medico: true, resultados: { include: { parametro: true } } }
        });
        if (!orden) return res.status(404).json({ error: 'Orden no encontrada' });
        res.json(orden);
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
};

exports.createOrden = async (req, res) => {
    try {
        const data = req.body;
        if (data.fecha_muestra) data.fecha_muestra = new Date(data.fecha_muestra);

        // Generar codigo_orden único
        const count = await prisma.ordenExamen.count();
        data.codigo_orden = `ORD-H-${new Date().getFullYear()}-${(count + 1).toString().padStart(5, '0')}`;

        const orden = await prisma.ordenExamen.create({
            data
        });
        res.status(201).json(orden);
    } catch (error) {
        res.status(400).json({ error: error.message });
    }
};"

