exports.getAllParametros = async (req, res) => {
    try {
        const { search } = req.query;
        let where = { activo: true };

        if (search) {
            where = {
                ...where,
                OR: [
                    { nombre: { contains: search } },
                    { codigo: { contains: search } }
                ]
            };
        }

        const parametros = await prisma.parametroClinico.findMany({
            where,
            take: 50, // Limit to 50 for autocomplete performance
            orderBy: { nombre: 'asc' }
        });
        res.json(parametros);
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
};"

