"exports.createOrden = async (req, res) => {
    try {
        const { pruebas, ...ordenData } = req.body;

        // Defaults if missing
        if (!ordenData.fecha_muestra) ordenData.fecha_muestra = new Date();
        else ordenData.fecha_muestra = new Date(ordenData.fecha_muestra);

        // Generar codigo_orden único
        const count = await prisma.ordenExamen.count();
        ordenData.codigo_orden = `ORD-H-${new Date().getFullYear()}-${(count + 1).toString().padStart(5, '0')}`;
        ordenData.estado = 'PENDIENTE';

        // Construir la estructura anidada para insertar resultados automáticamente
        const resultadosData = pruebas ? pruebas.map(paramId => ({
            parametro_id: paramId,
            valor_numerico: null,
            valor_texto: null,
            fuera_rango: false
        })) : [];

        const orden = await prisma.ordenExamen.create({
            data: {
                ...ordenData,
                resultados: {
                    create: resultadosData
                }
            },
            include: { resultados: true }
        });
        res.status(201).json(orden);
    } catch (error) {
        res.status(400).json({ error: error.message });
    }
};"

