"  const loadData = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`http://localhost:5003/api/ordenes/${ordenId}`);
      const selectedOrden = res.data;

      if (!selectedOrden) throw new Error("Orden no encontrada");
      setOrden(selectedOrden);

      // Extract the real parameters that were selected in the Smart Search (NuevaOrden)
      const realParams = selectedOrden.resultados.map(r => r.parametro);
      setParametros(realParams);

      const initialResults = {};
      selectedOrden.resultados.forEach(r => {
        initialResults[r.parametro_id] = { 
          valor_numerico: r.valor_numerico || '', 
          valor_texto: r.valor_texto || '' 
        };
      });
      setResultados(initialResults);

    } catch (err) {
      setError('Error al cargar la información de la orden');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };"

